import os,glob,re
session_dir = os.environ['RLM_SESSION_DIR']
basename = os.path.basename(session_dir)
original_path = os.path.join(session_dir, '../../sessions', basename + '.jsonl')

t=open(original_path).read().replace('\\n','\n')

# Find Test input section more carefully
lines = t.split('\n')
in_test_input = False
grid_rows = []
for i, line in enumerate(lines):
    if 'Test input (12x28):' in line:
        in_test_input = True
        continue
    if in_test_input and 'Wrong attempts' in line:
        break
    if in_test_input:
        # Remove JSON artifacts from the beginning/end of line
        line_clean = line.strip()
        if not line_clean.startswith('{') and not line_clean.startswith('"'):
            if line_clean:
                row_parts = line_clean.replace('Reply with exactly one action JSON on the last line."}],"timestamp":', '').split(',')
                if len(row_parts) == 30 and all(x.isdigit() for x in row_parts):
                    grid_rows.append([int(x) for x in row_parts])
                else:
                    # Look for numeric patterns
                    numbers = re.findall(r'-?\d+', line_clean)
                    if len(numbers) >= 5:
                        grid_rows.append([int(n) for n in numbers[:30]])

print("Found", len(grid_rows), "rows")
if grid_rows:
    print("First row:", grid_rows[0][:10], "...")
    print("Last row:", grid_rows[-1][:10], "...")

